  "status": "SUPPORTED",
  "claim": {
    "component_id": "C024.component",
    "value": "Recurrence after safe simulated reintroduction would strengthen the causal support supplied by a reproducible decrease after removing responsibility ambiguity.",
    "scope": "An additional evidentiary contribution conditional on the removal response and safe simulated recurrence; it does not establish live-effect magnitude or exclude alternative causes.",
