      ],
      "support_status": "SUFFICIENT",
      "rationale": "P018 supplies the additional causal support attributed to simulated recurrence; P029 supplies the limits on that support."
    }
  },
  "signal_basis": {
    "component_id": "C024.signal_basis",
    "value": "Missing attachments decrease reproducibly after responsibility becomes explicit. In a safe simulation alternating responsibility conditions across comparable fictitious tasks, missing attachments recur with ambiguity and improve again when clarity returns.",
    "scope": "The removal comparison uses comparable covered orders and a consistent inspection interval. Reintroduction provides simulation-specific evidence without weakening live controls.",
    "provenance": {
      "refs": [
        {
          "source_id": "P009",
